        process where process.name == "PsExec.exe"
}

rule ransomware_execution {
  meta:
    author = "SOC Team"
  description = "Detects ransomware execution"
  tags = "ransomware"

  strings:
    $ = "encrypted files"

  condition:
    any of them {
      process_name == "ransomware.exe"
      or process_name == "winrar.exe"
    }
}

